\title{Torsionness of Iwasawa Modules That Are Finitely Generated Over the Coefficient Ring}
\author{Aristotle}
\date{June 28, 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $R$ be an integral domain and let $R[[X]]$ denote its ring of formal power series in one variable. The ring $R[[X]]$ is the prototype of an \emph{Iwasawa algebra}: when $R = \Zp$ is the ring of $p$-adic integers, $\Lam := \Zp[[T]]$ is the completed group ring $\Zp[[\Gal(N_\infty/k)]]$ of the Galois group of a $\Zp$-extension $N_\infty/k$, and the \emph{unramified Iwasawa module} $X_\Sigma(N_\infty)$ is a finitely generated $\Lam$-module whose torsionness is a central conjecture generalizing Greenberg's conjecture. We isolate, prove, and formalize the algebraic engine underlying torsionness in the bounded-rank regime. Concretely, we prove that \textbf{any module $M$ over $R[[X]]$ which is finitely generated as a module over the coefficient ring $R$ is $\Lam$-torsion}: there exists a single nonzero power series $s \in R[[X]]$ annihilating every element of $M$. The proof reduces the structure of $M$ over $R[[X]]$ to a finite-dimensional linear-algebra fact about the $R$-linear endomorphism $\varphi$ ``multiplication by $X$,'' via the Cayley--Hamilton theorem. We delineate the correct hypothesis (finite generation over $R$, not over $R[[X]]$), exhibit the standard counterexample $M = R[[X]]$, and discuss how the resulting characteristic element feeds the structure theory of Iwasawa modules and the invariants $\mu$ and $\lambda$.
\end{abstract}

\noindent\textbf{Keywords:} Iwasawa algebra, power series ring, torsion module, Cayley--Hamilton, characteristic ideal, $\Zp$-extension, Greenberg's conjecture, $\lambda$-invariant.

\section{Introduction}

\subsection{Background and motivation}
Iwasawa theory studies the arithmetic of a number field $k$ along an infinite tower
\[
k = k_0 \subset k_1 \subset k_2 \subset \cdots \subset N_\infty = \bigcup_n k_n,
\]
a \textbf{$\Zp$-extension}: a Galois extension $N_\infty/k$ whose Galois group $\Gamma := \Gal(N_\infty/k)$ is topologically isomorphic to the additive group $\Zp$. The completed group ring
\[
\Lam := \Zp[[\Gamma]] \cong \Zp[[T]]
\]
is the \textbf{Iwasawa algebra}; a topological generator $\gamma$ of $\Gamma$ corresponds to $1+T$, so the augmentation element $\gamma - 1$ corresponds to $T$. The ring $\Zp[[T]]$ is a complete, regular, local, two-dimensional unique factorization domain, with maximal ideal $(p,T)$.

The principal objects are \textbf{Iwasawa modules}: finitely generated $\Lam$-modules arising as inverse limits up the tower. The most important is the unramified Iwasawa module
\[
X_\Sigma(N_\infty) = \Gal\!\left(M_\Sigma(N_\infty)/N_\infty\right),
\]
where $M_\Sigma(N_\infty)$ is the maximal abelian pro-$p$ extension of $N_\infty$ unramified outside a set $\Sigma$ of $p$-adic primes. A foundational conjecture, generalizing \textbf{Greenberg's conjecture} to arbitrary $\Sigma$-ramified $\Zp$-extensions, asserts:
\begin{conjecture}
$X_\Sigma(N_\infty)$ is a torsion $\Lam$-module; equivalently, $\rank_\Lam X_\Sigma(N_\infty) = 0$.
\end{conjecture}

Torsionness is the gateway to the structure theory: only for torsion modules can one define the \textbf{characteristic ideal}, decompose the module (up to finite kernel and cokernel) into elementary pieces $\Lam/(f_i^{e_i})$, and extract the invariants $\mu, \lambda$ governing the growth law
\[
\operatorname{ord}_p\!\big(\#\,\Cl(k_n)\big) = \mu\, p^n + \lambda\, n + \nu \qquad (n \gg 0).
\]

\subsection{The algebraic engine}
We isolate the purely algebraic core of torsionness in the regime where the module is additionally \textbf{finitely generated over $\Zp$} (the case $\mu = 0$, $\lambda < \infty$). We work in maximal generality, replacing $\Zp$ by an arbitrary integral domain $R$ and $\Lam$ by $R[[X]]$.
\begin{theorem}[Main Theorem, informal]
Let $M$ be a module over $R[[X]]$ which is finitely generated as an $R$-module. Then $M$ is $\Lam$-torsion: there is a nonzero $s \in R[[X]]$ with $s \cdot x = 0$ for all $x \in M$.
\end{theorem}

\section{Preliminaries}
Throughout, $R$ is a commutative ring; from Section~\ref{sec:results} onward $R$ is an integral domain. Write $R[X]$ for the polynomial ring and $R[[X]]$ for the formal power-series ring. There is a canonical injective $R$-algebra homomorphism
\[
\iota : R[X] \hookrightarrow R[[X]], \qquad \textstyle\sum_i a_i X^i \mapsto \sum_i a_i X^i,
\]
whose injectivity is decisive below.

\paragraph{Modules and scalar towers.} We consider an abelian group $M$ with two compatible module structures, over $R$ and over $R[[X]]$, satisfying the \textbf{scalar-tower} axiom: the $R$-action factors through the $R[[X]]$-action along $R \to R[[X]]$.

\paragraph{Finite generation.} $M$ is \emph{finite over $R$} if it is generated by finitely many elements as an $R$-module, equivalently a quotient of $R^n$.

\begin{theorem}[Cayley--Hamilton, monic form]\label{thm:ch}
Let $R$ be a commutative ring and $M$ a finite $R$-module. For every $\psi \in \End_R(M)$ there exists a \emph{monic} polynomial $q \in R[X]$ with $q(\psi) = 0$ in $\End_R(M)$.
\end{theorem}

\paragraph{Torsion.} $M$ is \textbf{$R[[X]]$-torsion} if there exists a single nonzero $s \in R[[X]]$ with $s\cdot x = 0$ for all $x \in M$. When $R$ is a domain (so $R[[X]]$ is a domain), this is equivalent to $\Ann_{R[[X]]}(M) \neq (0)$, i.e. $\rank_{R[[X]]} M = 0$.

\section{Definitions and statement of results}\label{sec:results}

\subsection{The endomorphism ``multiply by $X$''}
\begin{definition}[\texttt{phiT}]
Let $M$ be an $R[[X]]$-module that is also an $R$-module via a scalar tower. Define the $R$-linear endomorphism
\[
\varphi := \lsmul_R(X) \in \End_R(M), \qquad \varphi(x) = X \cdot x.
\]
$R$-linearity is exactly the scalar-tower compatibility: $\varphi(ax) = X\cdot(ax) = a\cdot(Xx) = a\,\varphi(x)$.
\end{definition}

\subsection{Main results}
Assume from now on that $R$ is an integral domain.
\begin{lemma}[\texttt{aeval\_phiT\_eq}]\label{lem:eq}
The $R$-algebra homomorphisms $R[X] \to \End_R(M)$ given by $\aeval_\varphi$ and $\lsmul_R \circ \iota$ coincide.
\end{lemma}
\begin{lemma}[\texttt{aeval\_phiT\_apply}]\label{lem:apply}
For all $q \in R[X]$ and $x \in M$, \ $q(\varphi)(x) = \iota(q)\cdot x = q(X)\cdot x$.
\end{lemma}
\begin{lemma}[\texttt{exists\_monic\_aeval\_phiT\_eq\_zero}]\label{lem:monic}
If $M$ is finite over $R$, there exists a monic $q \in R[X]$ with $q(\varphi) = 0$.
\end{lemma}
\begin{theorem}[\texttt{exists\_ne\_zero\_aeval\_phiT\_eq\_zero}]\label{thm:nonzero}
If $M$ is finite over $R$, there exists a nonzero $q \in R[X]$ with $q(\varphi) = 0$.
\end{theorem}
\begin{theorem}[Main Theorem, \texttt{isTorsion\_of\_finite}]\label{thm:main}
Let $R$ be an integral domain and $M$ an $R[[X]]$-module finite over $R$. Then there exists a nonzero $s \in R[[X]]$ with $s \cdot x = 0$ for every $x \in M$; one may take $s = \iota(q) = q(X)$ for the polynomial $q$ of Theorem~\ref{thm:nonzero}.
\end{theorem}

\section{Proofs}

\begin{proof}[Proof of Lemma~\ref{lem:eq}]
Both sides are $R$-algebra maps out of $R[X]$, which is free on the single generator $X$; two such maps are equal iff they agree on $X$. The left map sends $X \mapsto \varphi = \lsmul_R(X)$ by definition of $\aeval$. The right sends $X \mapsto \lsmul_R(\iota(X)) = \lsmul_R(X) = \varphi$ since $\iota(X) = X$. They agree.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:apply}]
Apply Lemma~\ref{lem:eq} to $q$ and evaluate at $x$:
\[
q(\varphi)(x) = (\aeval_\varphi q)(x) = (\lsmul_R \circ \iota)(q)(x) = \iota(q)\cdot x. \qedhere
\]
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:monic}]
Apply Theorem~\ref{thm:ch} to the finite $R$-module $M$ and $\psi = \varphi$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:nonzero}]
Let $q$ be the monic polynomial of Lemma~\ref{lem:monic}. A monic polynomial over a nonzero ring has leading coefficient $1 \neq 0$, hence $q \neq 0$. Since $R$ is a domain it is nonzero, so $q \neq 0$ and $q(\varphi) = 0$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
Let $q$ be the nonzero polynomial of Theorem~\ref{thm:nonzero} with $q(\varphi) = 0$, and set $s := \iota(q) = q(X)$.

\emph{$s \neq 0$:} $\iota$ is injective; if $\iota(q) = 0 = \iota(0)$ then $q = 0$, a contradiction.

\emph{$s$ annihilates $M$:} for $x \in M$, by Lemma~\ref{lem:apply}, $s\cdot x = \iota(q)\cdot x = q(\varphi)(x) = 0$.

As $x$ was arbitrary, the single nonzero $s$ kills $M$, so $M$ is $\Lam$-torsion.
\end{proof}

\section{The hypothesis is essential}
\begin{example}[The naive formulation fails]
Take $M = R[[X]]$ as a module over itself; it is generated by $1$, hence finitely generated \emph{over $R[[X]]$}. Yet $M$ is not torsion: for nonzero $s$, $s\cdot 1 = s \neq 0$, so $\Ann_{R[[X]]}(R[[X]]) = (0)$ and $\rank_{R[[X]]} M = 1$. The obstruction is that $R[[X]]$ is \emph{not} finite over $R$: the family $1, X, X^2, \dots$ is $R$-independent, and ``multiply by $X$'' is the shift, satisfying no nonzero polynomial.
\end{example}
The genuine hypothesis is finite generation \emph{over the coefficient ring} $R$. This matches the standard slogan: a finitely generated $\Lam$-module that is also finitely generated over $\Zp$ is automatically $\Lam$-torsion (the case $\mu = 0$, $\lambda < \infty$).

\section{Significance in Iwasawa theory}
Once $M$ is torsion, its \textbf{characteristic ideal} $\charideal_\Lam(M) = \prod_{\mathfrak p} \mathfrak p^{\ell_{\mathfrak p}(M_{\mathfrak p})}$ (over height-one primes) is a nonzero principal ideal; the Main Theorem provides an explicit nonzero annihilator, hence a witness $\charideal_\Lam(M) \neq (0)$. A generator $g$ factors, by Weierstrass preparation in $\Zp[[T]]$, as $g = p^\mu \cdot U \cdot P$ with $U$ a unit and $P$ a distinguished polynomial of degree $\lambda$. In the bounded-rank regime $\mu = 0$; if $M$ is free of rank $r$ over $\Zp$, then $\det(T\cdot\mathrm{Id} - \varphi)$ is (after unit normalization) $P$, with $\lambda = r = \rank_{\Zp} M$. A control theorem then yields finite layers $M/\omega_n M$ of order $p^{e_n}$ with $e_n = \mu p^n + \lambda n + \nu$ for $n \gg 0$, recovering Iwasawa's class-number growth law.

\section{Algorithms and computation}
In the bounded-rank case $\varphi$ is an $r\times r$ matrix and the pipeline is linear algebra.

\paragraph{Algorithm A (characteristic annihilator).} Given $\Phi$ representing $\varphi$, compute $\chi_\Phi(X) = \det(XI - \Phi)$, a monic (hence nonzero) polynomial with $\chi_\Phi(\Phi) = 0$; then $\iota(\chi_\Phi)$ annihilates $M$. Cost: $O(r^3)$ ring operations.

\paragraph{Algorithm B (Weierstrass invariants).} Given $g = \sum_i a_i T^i$ to $p$-adic precision, set $\mu = \min_i v_p(a_i)$ and $\lambda = \min\{i : v_p(a_i) = \mu\}$.

\section{Applications and future work}
The Main Theorem certifies torsionness whenever the relevant unramified module is finite over $\Zp$, yielding unconditional torsionness in many CM and abelian cases; provides an effective nonzero element of $\charideal_\Lam(M)$; and applies over any integral domain $R$, covering $\mathcal{O}[[T]]$ for $\mathcal{O}$ the integers of a finite extension of $\mathbb{Q}_p$. Concrete next targets include: identifying $\charideal_\Lam(M)$ with the characteristic polynomial of $\varphi$ (degree $= \lambda$) for free $M$; formalizing Weierstrass preparation to extract $(\mu,\lambda)$; a control theorem for finite coinvariants $M/\omega_n M$; the pseudo-isomorphism structure theorem over $\Zp[[T]]$; and the sharp criterion that $M$ is torsion iff $\rank_\Lam M = 0$.

