function weierstrass_invariants(coeffs a_0..a_d, prime p, precision cap):
    for each i:  v_i <- p_adic_valuation(a_i)   # capped at cap
    mu     <- min_i v_i
    lambda <- least i with v_i == mu
    return (mu, lambda)        # g = p^mu * unit * distinguished_poly(deg lambda)
